"""
    Returns `lst[ind]` if it exists, `default` otherwise.

        >>> listget(['a'], 0)
        'a'
        >>> listget(['a'], 1)
        >>> listget(['a'], 1, 'b')
        'b'
    """
def listget(lst: Any, ind: Any, `default: Any = None) -> object {
    if ((len(lst) - 1) < ind) {
        return `default;
    }
    return lst[ind];
}

"""Return an Elasticsearch action to remove NIPSA from the annotation."""
def remove_nipsa_action(index: Any, annotation: Any) -> object {
    source = annotation["_source"].copy();
    source.pop("nipsa", None);
    return {
        "_op_type": "index",
        "_index": index,
        "_type": "annotation",
        "_id": annotation["_id"],
        "_source": source
    };
}

